import {UI} from '../shared/copy.js';
import {DESIGN_COPY} from '../shared/design-copy.js';
import {validTemplate} from '../shared/templates.js';
import {MENU} from '../shared/menu.js';
import {LANGS,esc,money,getLang,setLang,languageOptions,icon} from '../shared/core.js';
import {readState,ensureSession,sessionOf,menuFor,updateCart,cartTotal,cartQuote,placeOrder,quota,recordChat,addRequest,updateProfile,playGame,STORAGE_KEY} from '../shared/state.js';
import {QUESTIONS,REPLIES,classify,resolveAnswer,answerText,storeGreeting} from '../shared/chat.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
let lang=getLang(),tab=['menu','chat','games','orders','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'menu',category='all',query='',spinning=false,toastTimer,gamePhase=null,gameTimer;
const pageParams=new URLSearchParams(location.search),isPreview=pageParams.get('preview')==='1';
const table=Math.min(999,Math.max(1,Number.parseInt(new URLSearchParams(location.search).get('table'),10)||3));
let sessionId;try{sessionId=ensureSession(table,lang)}catch{sessionId=null;}
const t=k=>DESIGN_COPY[lang]?.[k]||UI[lang][k]||k;
const state=()=>readState();const visit=()=>sessionOf(state(),sessionId);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3600)}
function safe(fn){try{return fn()}catch(e){toast(t(UI[lang][e.message]?e.message:'storageError'));return null}}
function setLanguage(v){if(!LANGS[v])return;lang=v;setLang(lang);safe(()=>updateProfile(sessionId,visit()?.nickname||'',visit()?.consent||false,lang));render();}
function currentTemplate(){return validTemplate(pageParams.get('template')||state().store.template)}
function applyTheme(){document.body.className='template-'+currentTemplate();}
function brand(){return `<div class="brand"><img src="assets/brand.png" alt="주모 Jumo"><div><b>${esc(state().store.name)}</b><small>jumo · joseon hip-hop</small></div></div>`}
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'side-nav'}" aria-label="${esc(t('menu'))}">${['menu','chat','games','orders','profile'].map(x=>`<button class="nav-item ${tab===x?'active':''}" data-tab="${x}" ${tab===x?'aria-current="page"':''}>${icon(x)}<span>${esc(t(x))}</span></button>`).join('')}</nav>`}
function render(){applyTheme();document.documentElement.lang=lang;document.title=`${state().store.name} · Jumo | modu ai · 모두의 AI`;app.innerHTML=`<aside class="sidebar">${brand()}${nav()}<div class="side-bottom"><a href="owner.html?lang=${lang}">${esc(t('owner'))} ${icon('arrow')}</a><a href="../?lang=${lang}">${esc(t('book'))} ${icon('arrow')}</a><div class="modu-brand">modu ai<span>모두의 AI</span></div></div></aside><main class="page"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="table-label">${esc(t('table'))}<strong>${String(table).padStart(2,'0')}</strong></div><div class="top-right"><button class="profile-orb icon-button" data-tab="profile" aria-label="${esc(t('profile'))}">${icon('profile')}</button><label class="lang-picker">${icon('globe')}<select id="language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select></label><button class="icon-button" data-action="staff" aria-label="${esc(t('staff'))}">${icon('bell')}</button></div></header><div class="demo-bar">${esc(t(isPreview?'previewOnly':'demoNote'))}</div><div class="content-grid"><section class="view" id="view">${renderView()}</section><aside class="basket-panel" id="basket-panel">${basketContent()}</aside></div><p class="caption"><a href="../?lang=${lang}">modu ai · 모두의 AI</a> &nbsp; / &nbsp; <a href="owner.html?lang=${lang}">${esc(t('owner'))} ${icon('arrow')}</a></p></main>${nav(true)}${cartButton()}`;
 if(tab==='chat')scrollChat();}
function cartButton(){const v=visit(),qty=Object.values(v?.cart||{}).reduce((n,x)=>n+x,0);return qty?`<button class="mobile-cart" data-action="cart"><span>${qty}</span>${esc(t('cart'))}<strong>${money(cartTotal(state(),sessionId))}</strong></button>`:''}
function renderView(){if(!sessionId)return `<div class="glass">${esc(t('storageError'))}</div>`;if(tab==='chat')return chatView();if(tab==='games')return gamesView();if(tab==='orders')return ordersView();if(tab==='profile')return profileView();return menuView();}
function menuView(){return `<div class="menu-welcome"><p>${esc(t('greeting'))}${visit()?.consent&&visit()?.nickname?', '+esc(visit().nickname):''}</p><h1>${t('menuHeadline').split('\n').map((line,i)=>`<span class="${i?'headline-accent':''}">${esc(line)}</span>`).join('')}</h1></div><div class="searchbox">${icon('search')}<input id="menu-search" value="${esc(query)}" placeholder="${esc(t('search'))}" aria-label="${esc(t('search'))}" maxlength="60"></div><div class="categories" aria-label="${esc(t('menu'))}">${[['all',0],['jeon',1],['anju',2],['dry',3],['sweet',4]].map(([k,a])=>`<button class="category ${category===k?'active':''}" data-category="${k}" aria-pressed="${category===k}"><span class="category-art cat-${a}" aria-hidden="true"></span><span>${esc(t(k))}</span></button>`).join('')}</div><div class="hero"><img src="assets/jeon.jpg" alt="${esc(MENU.find(x=>x.id==='m04').name[lang])}" fetchpriority="high"><div class="hero-content"><span class="pill">${icon('spark')} ${esc(t('featured'))}</span><h2>${esc(t('heroTitle'))}</h2><p>${esc(t('heroSub'))}</p><button class="primary" data-question="qRecommend">${esc(t('heroCta'))}${icon('arrow')}</button></div></div><div class="section-row"><h2>${esc(t('popular'))}</h2><button class="text-button" data-action="print-menu" aria-label="${esc(t('downloadMenu'))}">${icon('orders')}</button></div><div class="menu-grid" id="menu-grid">${menuCards()}</div><p class="caption">${esc(t('priceNote'))}</p>`}
function menuCards(){const items=menuFor(state()).filter(x=>(category==='all'||x.category===category)&&[...Object.values(x.name),x.description[lang]].join(' ').toLowerCase().includes(query.toLowerCase()));return items.length?items.map(x=>`<article class="food-card">${!x.available?`<span class="sold-tag">${esc(t('soldOut'))}</span>`:''}<button class="food-photo" data-detail="${x.id}" aria-label="${esc(x.name[lang])} — ${esc(t('viewDetails'))}"><img src="${x.image}" alt="${esc(x.name[lang])}" loading="lazy" width="600" height="450"></button><div class="food-info"><button class="food-title" data-detail="${x.id}">${esc(x.name[lang])}</button><p>${esc(x.description[lang])}</p><div class="food-bottom"><b>${money(x.price)}</b><button class="add-button" data-add="${x.id}" aria-label="${esc(x.name[lang])} ${esc(t('add'))}" ${x.available?'':'disabled'}>${icon('plus')}</button></div></div></article>`).join(''):`<p class="empty">${esc(t('emptySearch'))}</p>`}
function lines(){const s=state(),v=visit();return menuFor(s).filter(x=>v?.cart[x.id]).map(x=>`<div class="basket-line"><b>${esc(x.name[lang])}</b><div class="line-bottom"><div class="stepper"><button data-qty="${x.id}" data-delta="-1" aria-label="${esc(x.name[lang])} −">−</button><span>${v.cart[x.id]}</span><button data-qty="${x.id}" data-delta="1" aria-label="${esc(x.name[lang])} +">+</button></div><span>${money(x.price*v.cart[x.id])}</span></div></div>`).join('')}
function basketContent(){const s=state(),has=Object.keys(visit()?.cart||{}).length;return `<h3>${esc(t('cart'))}</h3><p>${esc(t('table'))} ${String(table).padStart(2,'0')}</p>${has?lines():`<div class="basket-art">${icon('bag')}</div><div class="basket-empty">${esc(t('emptyCart'))}</div>`}<div class="basket-total"><span>${esc(t('total'))}</span><strong>${money(cartTotal(s,sessionId))}</strong></div><button class="primary" data-action="checkout" data-quote="${esc(cartQuote(s,sessionId))}" ${has?'':'disabled'}>${esc(t('confirmOrder'))}${icon('arrow')}</button><p class="caption">${esc(t('orderNote'))}</p><button class="text-button wide-button" data-action="staff">${esc(t('staff'))}</button><a class="foot-link" href="owner.html?lang=${lang}">${esc(t('owner'))} ${icon('arrow')}</a>`}
function openDialog(title,body){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function showCart(){openDialog(t('cart'),`<div id="cart-dialog">${basketContent()}</div>`)}
function detail(id){const x=menuFor(state()).find(x=>x.id===id);if(!x)return;modal.innerHTML=`<div class="modal-head"><span class="pill">${esc(t(x.category))}</span><button class="icon-button" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div><img class="detail-photo" src="${x.image}" alt="${esc(x.name[lang])}"><div class="detail-body"><h2>${esc(x.name[lang])}</h2><p>${esc(x.description[lang])}</p><p class="caption">${esc(t('allergyNote'))}</p><strong>${money(x.price)}</strong><button class="primary" data-add="${x.id}" ${x.available?'':'disabled'}>${icon('plus')}${esc(t(x.available?'add':'soldOut'))}</button><p class="caption">${esc(t('priceNote'))}</p></div>`;modal.showModal();}
function chatView(){const v=visit();return `<div class="section-intro"><h1>${esc(t('chat'))}</h1><p>${esc(t('chatSubtitle'))}</p></div><div class="chat-shell"><div class="chat-head">${brand()}<button class="icon-button" data-action="staff" aria-label="${esc(t('staff'))}">${icon('bell')}</button></div><div class="chat-history" id="chat-history" role="log" aria-live="polite"><div class="message"><small>${esc(state().store.name)}</small>${esc(storeGreeting(lang,state().store.name))}</div>${v.messages.map(m=>`<div class="message user">${esc(m.text)}</div><div class="message"><small>${esc(state().store.name)}</small>${esc(answerText(m,lang))}${m.key==='replyRecommend'&&menuFor(state()).find(x=>x.id==='m04').available?`<button class="text-button" data-add="m04">+ ${esc(MENU.find(x=>x.id==='m04').name[lang])}</button>`:''}${m.key==='limitReached'||m.key==='unknown'?`<button class="text-button" data-action="staff">${esc(t('staff'))}</button>`:''}</div>`).join('')}</div><div class="chat-suggestions">${QUESTIONS.map(k=>`<button class="chip" data-question="${k}">${esc(t(k))}</button>`).join('')}</div><form class="chat-input" id="chat-form"><input id="chat-input" name="question" maxlength="400" autocomplete="off" placeholder="${esc(t('chatPlaceholder'))}" aria-label="${esc(t('chatPlaceholder'))}" required><button type="submit" aria-label="${esc(t('send'))}">↑</button></form><div class="chat-foot">${esc(t('scopeNote'))} · ${esc(t('messagesLeft'))} ${quota(state(),sessionId)}</div></div>`}
function scrollChat(){const el=$('#chat-history');if(el)el.scrollTop=el.scrollHeight;}
function ask(text,question){if(!text.trim())return;const resolved=resolveAnswer(text,question,state(),lang);const result=safe(()=>recordChat(sessionId,text,resolved.key,lang,resolved.key!=='offTopic',resolved.data));if(!result)return;tab='chat';history.replaceState(null,'','#chat');render();$('#chat-input')?.focus();}
function handArt(hand,cls=''){return `<img class="hand-art ${cls}" src="assets/game/hand-${hand}.png" alt="${esc(t(hand))}" width="180" height="180">`}
function rewardArt(index,cls=''){return `<span class="reward-art reward-${index} ${cls}" aria-hidden="true"></span>`}
function gamesView(){const v=visit(),r=v.games.rps,w=v.games.roulette,revealing=gamePhase?.kind==='rps',turning=gamePhase?.kind==='roulette';return `<div class="section-intro game-intro"><span class="pill">Jumo play club</span><h1>${esc(t('gameTitle'))}</h1><p>${esc(t('gameNote'))}</p></div><div class="game-grid"><article class="glass game-card rps-card"><div class="game-card-heading"><div><span class="pill">${esc(t('free'))}</span><h2>${esc(t('rps'))}</h2></div>${icon('games')}</div><p>${esc(t('rpsDesc'))}</p><div class="duel-stage ${revealing?'revealing':''}"><div><span>${esc(t('you'))}</span>${handArt(r?r.choice:'rock','player-hand')}</div><b class="versus">vs</b><div><span>주모</span>${handArt(r&&!revealing?r.opponent:'rock','host-hand')}</div></div><div class="game-result ${r&&!revealing&&r.outcome==='win'?'is-win':''}" aria-live="polite">${revealing?esc(t('gameReveal')):r?`${esc(t(r.capped?'rewardCap':r.outcome))}<small>${esc(t('chooseHand'))}: ${esc(t(r.choice))} · ${esc(t('jumoChoice'))}: ${esc(t(r.opponent))}</small>`:esc(t('gameReady'))}</div><div class="rps-hands">${['rock','paper','scissors'].map(k=>`<button class="hand ${r?.choice===k?'selected':''}" data-hand="${k}" ${r||spinning?'disabled':''}>${handArt(k)}<small>${esc(t(k))}</small></button>`).join('')}</div>${r?`<p class="game-foot">${esc(t('replayHint'))}</p>`:''}</article><article class="glass game-card wheel-card"><div class="game-card-heading"><div><span class="pill">${esc(t('free'))}</span><h2>${esc(t('roulette'))}</h2></div>${icon('spark')}</div><p>${esc(t('rouletteDesc'))}</p><div class="roulette-wrap"><div class="wheel" id="wheel" style="transform:rotate(${w&&!turning?1800+360-(w.index*90+45):0}deg)"><img class="wheel-disc" src="assets/game/reward-wheel.png" alt="${esc(t('roulette'))}" width="600" height="600">${[0,1,2,3].map((x,i)=>`<span class="wheel-prize" style="--angle:${i*90+45}deg">${rewardArt(x)}</span>`).join('')}</div><span class="wheel-center"><img src="assets/brand.png" alt="주모" width="48" height="48"></span></div><button class="primary wide-button" data-action="spin" ${w||spinning?'disabled':''}>${icon('spark')}${esc(t(turning?'spinning':w?'alreadyPlayed':'spin'))}</button><div class="game-result ${w&&!turning&&w.reward?'is-win':''}" id="wheel-result" aria-live="polite">${turning?esc(t('spinning')):w?esc(t(w.capped?'rewardCap':w.reward||'noPrize')):esc(t('spinReady'))}</div><div class="game-list">${['rewardTea','rewardSweet','rewardSnack','noPrize'].map((k,i)=>`<div>${rewardArt(i)}<span>${esc(t(k))}</span><small>25%</small></div>`).join('')}</div></article></div><section class="coupon-section"><div class="section-row"><h2>${esc(t('coupon'))}</h2>${icon('bag')}</div>${v.coupons.length?v.coupons.map(c=>`<div class="coupon">${rewardArt(['rewardTea','rewardSweet','rewardSnack'].indexOf(c.reward),'coupon-art')}<div><h3>${esc(t(c.reward))}</h3><code>${esc(c.code)}</code><p>${esc(t('couponNote'))}</p></div><span class="status ${c.used?'completed':''}">${esc(t(c.used?'couponUsed':'couponReady'))}</span></div>`).join(''):`<p class="empty glass">${esc(t('noCoupon'))}</p>`}</section><p class="caption">${esc(t('gameRules'))}</p>`}
function doGame(kind,choice){if(spinning)return;const result=safe(()=>playGame(sessionId,kind,choice));if(!result)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced){render();return;}spinning=true;gamePhase={kind,result};render();if(kind==='roulette'){requestAnimationFrame(()=>requestAnimationFrame(()=>{const wheel=$('#wheel');if(wheel)wheel.style.transform=`rotate(${1800+360-(result.index*90+45)}deg)`;}));}clearTimeout(gameTimer);gameTimer=setTimeout(()=>{spinning=false;gamePhase=null;if(tab==='games')render();},kind==='rps'?1100:3000);}
function ordersView(){const orders=state().orders.filter(o=>o.sessionId===sessionId).reverse();return `<div class="section-intro"><h1>${esc(t('orders'))}</h1><p>${esc(t('noRealPayment'))}</p></div>${orders.length?orders.map(o=>`<article class="glass order-card"><div class="order-header"><div><h3>#${String(o.number).padStart(3,'0')} · ${esc(t('table'))} ${o.table}</h3><small>${esc(new Date(o.at).toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit'}))}</small></div><span class="status ${o.status}">${esc(t(o.status))}</span></div>${o.lines.map(l=>`<div class="order-item"><span>${esc(MENU.find(x=>x.id===l.itemId)?.name[lang]||l.itemId)} × ${l.quantity}</span><b>${money(l.quantity*l.unitPrice)}</b></div>`).join('')}<div class="order-summary"><span>${esc(t('total'))}</span><strong>${money(o.total)}</strong></div><div class="order-statuses"><span>${esc(t('payCounter'))}</span><span class="status ${o.payment}">${esc(t(o.payment))}</span></div></article>`).join(''):`<div class="glass empty">${esc(t('emptyOrders'))}<br><button class="text-button" data-tab="menu">${esc(t('viewMenu'))}</button></div>`}`}
function profileView(){const v=visit();return `<div class="profile-wrap"><div class="section-intro"><h1>${esc(t('profileTitle'))}</h1><p>${esc(t('privacyNote'))}</p></div><form id="profile-form" class="glass"><label>${esc(t('nickname'))}<input name="nickname" value="${esc(v.nickname)}" maxlength="30" autocomplete="off"></label><label class="check-row"><input type="checkbox" name="consent" ${v.consent?'checked':''}><span>${esc(t('consent'))}</span></label><button class="primary">${esc(t('save'))}</button><p class="caption">${esc(t('table'))} ${v.table} · ${esc(LANGS[v.lang])}<br>${esc(t('localOnly'))}</p></form><div class="glass" style="margin-top:22px"><h3>${esc(t('feedback'))}</h3><form id="feedback-form"><textarea name="feedback" maxlength="400" placeholder="${esc(t('feedbackPlaceholder'))}" aria-label="${esc(t('feedback'))}" required></textarea><div class="form-actions"><button class="secondary">${esc(t('send'))}</button></div></form></div><div class="form-actions"><button class="text-button" data-action="new-visit">${esc(t('newVisit'))}</button><a class="secondary" href="owner.html?lang=${lang}">${esc(t('owner'))} ${icon('arrow')}</a></div></div>`}
function go(next){tab=next;history.replaceState(null,'','#'+tab);render();window.scrollTo({top:0,behavior:'instant'})}
function refreshBasket(){const target=$('#basket-panel');if(target)target.innerHTML=basketContent();const old=$('.mobile-cart');old?.remove();app.insertAdjacentHTML('beforeend',cartButton());if($('#cart-dialog'))$('#cart-dialog').innerHTML=basketContent();}
function welcome(){modal.innerHTML=`<div class="welcome"><img src="assets/brand.png" alt="주모 Jumo"><h2>${esc(t('chooseLanguage'))}</h2><p>주모 · Jumo</p><div class="lang-grid">${Object.entries(LANGS).map(([k,v])=>`<button data-welcome-lang="${k}" class="${lang===k?'active':''}">${v}</button>`).join('')}</div><button class="primary" data-action="start">${esc(t('start'))}${icon('arrow')}</button><p class="caption">${esc(t('demoNote'))}</p></div>`;if(!modal.open)modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){go(b.dataset.tab);return;}if(b.dataset.category){category=b.dataset.category;$('#view').innerHTML=menuView();return;}if(b.dataset.detail){detail(b.dataset.detail);return;}if(b.dataset.add){const value=safe(()=>updateCart(sessionId,b.dataset.add,1));if(value){toast(t('added'));refreshBasket();}return;}if(b.dataset.qty){safe(()=>updateCart(sessionId,b.dataset.qty,Number(b.dataset.delta)));refreshBasket();return;}if(b.dataset.question){ask(t(b.dataset.question),b.dataset.question);return;}if(b.dataset.hand){doGame('rps',b.dataset.hand);return;}if(b.dataset.welcomeLang){setLanguage(b.dataset.welcomeLang);welcome();return;}switch(b.dataset.action){case 'close':modal.close();break;case 'start':modal.close();try{sessionStorage.setItem('jumo-welcome','1')}catch{}break;case 'cart':showCart();break;case 'staff':safe(()=>addRequest(sessionId));toast(t('staffSent'));break;case 'checkout':{const requestId=crypto.randomUUID();const o=safe(()=>placeOrder(sessionId,requestId,b.dataset.quote));if(o){modal.close();go('orders');toast(t('orderSent'));}else{refreshBasket();}break;}case 'spin':doGame('roulette');break;case 'new-visit':openDialog(t('newVisit'),`<p>${esc(t('newVisitNote'))}</p><button class="primary" data-action="confirm-new">${esc(t('newVisit'))}</button>`);break;case 'confirm-new':{const newId=safe(()=>ensureSession(table,lang,true));if(newId){sessionId=newId;modal.close();go('menu');}break;}case 'print-menu':document.body.classList.add('print-menu');window.print();document.body.classList.remove('print-menu');break;}});
document.addEventListener('change',e=>{if(e.target.id==='language')setLanguage(e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){query=e.target.value;$('#menu-grid').innerHTML=menuCards()}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();ask(new FormData(e.target).get('question'));}if(e.target.id==='profile-form'){e.preventDefault();const data=new FormData(e.target);if(safe(()=>{updateProfile(sessionId,data.get('nickname'),data.has('consent'),lang);return true})){toast(t('saved'));render();}}if(e.target.id==='feedback-form'){e.preventDefault();const val=new FormData(e.target).get('feedback').trim();if(val){safe(()=>addRequest(sessionId,val));e.target.reset();toast(t('feedbackSent'));}}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&!spinning&&!isPreview){render();refreshBasket();}});
window.addEventListener('hashchange',()=>{const x=location.hash.slice(1);if(['menu','chat','games','orders','profile'].includes(x)){tab=x;render()}});
render();try{if(!isPreview&&!sessionStorage.getItem('jumo-welcome'))welcome()}catch{}
